WITH ranked AS (SELECT b.mktcode,b.tgtcode,b.bizdate,ROW_NUMBER() OVER (ORDER BY b.volume DESC,b.mktcode ASC,b.tgtcode ASC) AS rn,COUNT(*) OVER () AS population FROM `newzl`.`hsj_stock_hq_basic` AS b WHERE b.bizdate='2026-04-14') SELECT r.mktcode,r.tgtcode,r.bizdate FROM ranked AS r INNER JOIN `newzl`.`hsj_stock_hq_basic` AS b ON b.mktcode=r.mktcode AND b.tgtcode=r.tgtcode AND b.bizdate=r.bizdate WHERE r.rn<=10 AND b.turnover>100000000;
